from pathlib import Path
import json,hashlib
r=Path.cwd();s=r/'.local/step07-ci-response-lifecycle';f=s/'final-latest';w=r/json.loads((f/'workspace.json').read_text())['workspace'];rows=[]
roots=list((w/'.local/received-resource-tests').iterdir());assert len(roots)==2 # full check plus explicit latest5 controls
for root in roots:
 files={}
 for p in root.glob('*.json'):
  b=p.read_bytes();o=json.loads(b);files[p.name]={'path':str(p.relative_to(r)),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'reads':o['reads'],'states':[{'id':x['id'],'document':x['document'],'currentDocument':x['currentDocument'],'state':x['state'],'transport':x['transport'],'sha':x.get('sha')}for x in o['records']]}
 assert len(files)==5
 rows.append({'root':str(root.relative_to(r)),'cases':files})
http=list((w/'.local/step07/tests').iterdir());assert len(http)==1;records=[]
for mode in ['production','development']:
 p=http[0]/('r4-received-resources-'+mode+'.json');o=json.loads(p.read_text());processed=[x for x in o['records']if'/processed?'in x['url']];successful=[x for x in processed if x['state']=='received'and x['transport']=='finished'];assert len(successful)==5,(mode,len(successful));assert all(x['method']=='GET'and x['status']==200 and x['currentDocument']for x in successful)
 records.append({'mode':mode,'processedSuccessfulBrowserReads':len(successful),'processedTotalResponses':len(processed),'recordsOrigin':str(p.relative_to(r)),'originalSHA256':hashlib.sha256(p.read_bytes()).hexdigest(),'records':o['records']})
(s/'capture-verification.json').write_text(json.dumps({'source':json.loads((f/'workspace.json').read_text())['source'],'actualBrowserControls':rows,'actualStudioCapture':records,'noNewServerReads':'capture only reads actual Playwright response bodies; no fetch/readExport or retries added','CIExactRequest':'UNKNOWN originalCI has no request ID/navigation trace; local cancellation mechanism independently demonstrated'},indent=2)+'\n');print('latest5 controls in check+explicitrun; fullStudio processed reads5+5 actual receipts verified')
